def require(value,message):
    if not value:raise ValueError(message)
def sha(data):return hashlib.sha256(data).hexdigest()
def local(path):
    path=Path(path).resolve(strict=True);require(path.is_relative_to(repo),'Local artifact escaped repository')
    data=path.read_bytes();return {'path':path.relative_to(repo).as_posix(),'sha256':sha(data),'bytes':len(data)}
def sanitized(value):
    if isinstance(value,str):
        for old,new in [(str(repo),'<repo>'),(str(Path.home()),'<user-profile>')]:
            pattern=r'[\\/]+'.join(re.escape(part) for part in re.split(r'[\\/]+',old));value=re.sub(pattern,lambda match:new,value,flags=re.I)
        value=re.sub(r'(<S N="(?:User|Computer|PSComputerName)">)[^<]*(</S>)',r'\1&lt;local-identity&gt;\2',value)
        for key in ['USERNAME','COMPUTERNAME','USERDOMAIN']:
            if os.environ.get(key):value=re.sub(re.escape(os.environ[key]),'<local-identity>',value,flags=re.I)
        return value
    if isinstance(value,list):return [sanitized(item) for item in value]
    if isinstance(value,dict):return {key:sanitized(item) for key,item in value.items()}
    return value
def publish(name,data):
    path=destination/name;require(not path.exists(),'Refusing to replace public '+name)
    encoded=(json.dumps(sanitized(data),indent=2,ensure_ascii=False,allow_nan=False)+'\n').encode('utf-8')
    for literal in [str(repo),str(Path.home()),os.environ.get('USERNAME',''),os.environ.get('COMPUTERNAME',''),os.environ.get('USERDOMAIN','')]:
        if literal:
            pattern=r'[\\/]+'.join(re.escape(part) for part in re.split(r'[\\/]+',literal))
            require(not re.search(pattern,encoded.decode('utf-8'),re.I),'Private identity residue')
    require(not re.search(r'github_pat_[A-Za-z0-9_]{20}|ghp_[A-Za-z0-9]{20}|Bearer\s+[A-Za-z0-9_-]{20}',encoded.decode('utf-8')),'Token residue')
    path.write_bytes(encoded);result=local(path);print(json.dumps(result));return result
def read_capture(path):
    path=path.resolve(strict=True);require(path.is_relative_to(scratch),'Capture outside task media scratch')
    data=json.loads(path.read_text(encoding='utf-8'));require(data['source_revision']==EXPECTED_BASELINE,'Unexpected workflow baseline')
    require(all(data[key] for key in GUARDS),'Captured immutability guard failed')
    require(all(data['source_sha256_before'][name]==data['source_sha256_after'][name]==runtime[name] for name in RUNTIME),'Runtime differs across scopes/publication')
    for name,digest in data['copies_after'].items():require(local(repo/name)['sha256']==digest,'Application copy changed')
    for name,item in data['tools'].items():
        path_=Path(item['path'].replace('<repo>',str(repo)));require(local(path_)['sha256']==item['sha256']==data['tools_sha256_after'][name],'Tool changed')
    return path,data
def result_projection(result):return {'command_id':result['id'],**{key:result[key] for key in ['exit_code','timed_out','elapsed_seconds']}}
def report_projection(item):
    report=item['report'];output={key:item[key] for key in ['path','sha256','bytes']}
    fields={key:report[key] for key in ['schemaVersion','jobId','toolVersion','status','applicationExitCode','processingStatus','processingExitCode','nativeExitCode','presetId','presetVersion','presetCustomized','presetExperimental','settings','input','timing','warningCodes','reasonCodes','reporting'] if key in report}
    if report.get('reportType')=='preview':
        fields.update(reportType='preview',startedAtUtc=report['startedAtUtc'],endedAtUtc=report['endedAtUtc'],range=report['range'],timeline=report['timeline'],alignment=report['alignment'],matching=report['matching'],outputOrganization=report.get('outputOrganization'))
        fields['assets']={role:{key:asset[key] for key in ['path','exactFilters','frames','format','gainDb','measurements']} for role,asset in report['assets'].items()}
        fields['stages']={stage:{'arguments':item['arguments'],'inputSource':item['inputSource'],
            'process':{key:item['process'].get(key) for key in ['Started','ExitCode','Cancelled','OwnedProcessId','TimedOut','Error','CleanupError','Progress']}} for stage,item in report['stages'].items()}
    else:fields['output']={key:report['output'][key] for key in ['path','published','validity','format','verified','organization'] if key in report['output']}
    output['fields']=fields;return output
def cases_projection(cases,scope,path):
    result=[]
    for case in cases:
        entry={key:case[key] for key in ['id','passed','checks','controlled','host_facts','assets']}
        entry.update(result=result_projection(case['result']),source_scope=scope,complete_capture=local(path),reports=[report_projection(item) for item in case['reports']])
        for key in ['journal','direct_report_graph_reproduction']:
            if key in case:entry[key]=case[key]
        result.append(entry)
    return result
def references_projection(capture,path):
    return [{'id':reference['id'],'capture':local(path),'checks':reference['checks'],'result':result_projection(reference['result']),
        'reports':[report_projection(item) for item in reference['reports']],'assets':reference['assets'],'host_facts':reference['host_facts']} for reference in capture['references']]

runtime={name:local(repo/name)['sha256'] for name in RUNTIME};require(runtime['WinAudioClean.ps1']==EXPECTED_MAIN,'Unexpected frozen main')
