require({case['id'] for case in failed}=={'ps51-manifest-success','ps7-manifest-success'},'Unexpected initial failure')
require(all([key for key,value in case['checks'].items() if not value]==['manifest_relative_paths'] and case['result']['exit_code']==0 for case in failed),'Initial failure is not the isolated harness assertion')
require(len(retained)==8 and all(all(case['checks'].values()) for case in retained),'Eight retained cases not passing')
require(recovery['status']=='pass' and recovery['scope']['case_filter']==['manifest-success'] and recovery['scope']['shell_filter'] is None and len(recovery['cases'])==2,'Unexpected two-case recovery scope')
require(all(case['passed'] and all(case['checks'].values()) for case in recovery['cases']),'Recovery case failed')
