require(smoke['status']=='pass' and len(smoke['cases'])==3,'Smoke outcome differs')
first_harness=repo/initial['tested_harness']['path'];fixed_harness=repo/recovery['tested_harness']['path']
before=first_harness.read_text(encoding='utf-8');after=fixed_harness.read_text(encoding='utf-8')
old="[Path(item['inputPath']) for item in items]==[stereo,mono]";new="[Path(item['inputPath']).resolve() for item in items]==[stereo,mono]"
require(before.count(old)==1 and before.replace(old,new)==after,'Harness changed beyond one manifest path-equivalence assertion')
diff=''.join(difflib.unified_diff(before.splitlines(keepends=True),after.splitlines(keepends=True),fromfile='initial-tested-harness',tofile='corrected-tested-harness'))
for capture in [initial,recovery]:
