accepted.sort(key=lambda case:next(index for index,original in enumerate(initial['cases']) if original['id']==case['id']))
require(len(accepted)==10 and len({case['id'] for case in accepted})==10,'Final case ledger mismatch')
count_assets=lambda rows:sum(len(row['assets']) for row in rows)
case_assets=count_assets(accepted);ordinary_reference_assets=count_assets(initial['references'])+count_assets(recovery['references'])
counts={'accepted_cases':10,'accepted_normal_cases':8,'accepted_controlled_pre_request_cases':2,'retained_initial_passing_cases':8,'corrected_recovery_cases':2,
    'accepted_case_wavs':case_assets,'accepted_case_pcm_frame_comparisons':case_assets,
    'initial_scope_cases':10,'initial_scope_harness_pass':8,'initial_scope_harness_fail':2,'recovery_scope_cases':2,'recovery_scope_harness_pass':2,
    'ordinary_app_reference_wavs_across_final_scopes':ordinary_reference_assets,
    'superseded_initial_manifest_wavs':count_assets(failed),
    'all_actual_app_wavs_across_final_scopes':count_assets(initial['cases'])+count_assets(recovery['cases'])+ordinary_reference_assets,
    'direct_ffmpeg_preview_reproduction_wavs':sum(len(case.get('direct_report_graph_reproduction',[])) for case in accepted),
    'accepted_detailed_reports':sum(len(case['reports']) for case in accepted),'accepted_journals':sum('journal' in case for case in accepted),
    'top_level_app_invocations_across_final_scopes':sum(command['id'].startswith('app-') for capture in [initial,recovery] for command in capture['commands']),
    'fresh_builtins_management_invocations_across_final_scopes':len(initial['builtins_management'])+len(recovery['builtins_management'])}
require(case_assets==20 and ordinary_reference_assets==8 and counts['all_actual_app_wavs_across_final_scopes']==32 and counts['direct_ffmpeg_preview_reproduction_wavs']==8,'Unexpected realmedia count')
outcomes={scope:dict(collections.Counter(str(case['result']['exit_code']) for case in capture['cases'])) for scope,capture in [('initial10',initial),('recovery2',recovery)]}
accepted_outcomes=dict(collections.Counter(str(case['result']['exit_code']) for case in accepted))
